const record = $input.first().json.body;
if (!record || typeof record !== 'object') throw new Error('Missing webhook body');
const phone = String(record.userPhone || '').replace(/[\s()+-]/g, '');
if (!/^[1-9][0-9]{7,14}$/.test(phone)) throw new Error('Phone must include country code');
const template = $env.WHATSAPP_TEMPLATE_NAME;
const language = $env.WHATSAPP_TEMPLATE_LANGUAGE;
if (!template || !language) throw new Error('Configure an approved WhatsApp template and language');
if (!$env.WHATSAPP_PHONE_NUMBER_ID || !$env.WHATSAPP_API_VERSION) throw new Error('Configure Meta phone number ID and API version');
return [{json: {payload: {
  messaging_product: 'whatsapp', to: phone, type: 'template',
  template: {name: template, language: {code: language}, components: [{type: 'body', parameters:
    [record.name, record.campName, record.officerContact].map(value => ({type: 'text', text: String(value || 'Not available')}))
  }]}
}}}];
